# Fitness PDF generator

Save the Python below as `coach_pdf.py` in a working folder, then install once:

```bash
python3 -m venv .venv && .venv/bin/pip install weasyprint matplotlib
# the --png preview also needs poppler-utils (pdftoppm). Inter font is optional; it falls back to DejaVu Sans.
mkdir -p data out
.venv/bin/python coach_pdf.py plan   data/plan.json   out/plan.pdf   --png out/plan.png
.venv/bin/python coach_pdf.py report data/report.json out/report.pdf --png out/report.png
```

JSON fields are listed in the Fitness Coach skill. Fill them only from the athlete's own synced data. `"example": true` adds an EXAMPLE DATA banner; leave it off for real athletes. Missing scalars render as "-". In a report JSON `weeks` needs at least 2 entries.

```python
#!/usr/bin/env python3
"""Fitness Coach PDF generator. JSON in, PDF (+PNG) out."""
import json, sys, io, base64, datetime as dt, argparse, html
import matplotlib; matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib import font_manager
from weasyprint import HTML

INK, MUTED, LINE, BG, CARD, ACCENT = "#1B1D21", "#7C7F86", "#E6E2DB", "#F5F3EF", "#FFFFFF", "#FC5A1E"
SPORT = {
    "swim":  {"c": "#6F93B3", "n": "Swim"},
    "bike":  {"c": "#C7A465", "n": "Bike"},
    "run":   {"c": "#7FA585", "n": "Run"},
    "brick": {"c": "#B9826A", "n": "Brick"},
    "lift":  {"c": "#8F80AE", "n": "Lift"},
    "hyrox": {"c": "#5D6B75", "n": "HYROX"},
    "rest":  {"c": "#C9C4BB", "n": "Rest"},
}
ICON = {
 "swim": '<path d="M2 16c2 0 2-1.5 4-1.5S8 16 10 16s2-1.5 4-1.5 2 1.5 4 1.5 2-1.5 4-1.5M2 20c2 0 2-1.5 4-1.5S8 20 10 20s2-1.5 4-1.5 2 1.5 4 1.5 2-1.5 4-1.5"/><circle cx="16" cy="6" r="2"/><path d="M5 12l5-4 3 3"/>',
 "bike": '<circle cx="6" cy="16" r="4"/><circle cx="18" cy="16" r="4"/><path d="M6 16l4-7h5l3 7M10 9l2 7h-6M14 6h3"/>',
 "run":  '<circle cx="15" cy="4.5" r="2"/><path d="M8 21l3-6 3 2v4M6 11l3-3h4l2 4 3 1M11 8l-1 6"/>',
 "brick":'<circle cx="6" cy="17" r="3.5"/><circle cx="14" cy="17" r="3.5"/><path d="M6 17l3-5h4l1 5"/><path d="M19 4l2 3-2 3M16 7h5"/>',
 "lift": '<path d="M2 12h20M5 7v10M8 5v14M16 5v14M19 7v10"/>',
 "hyrox":'<path d="M13 2L4 14h7l-1 8 9-12h-7z"/>',
 "rest": '<path d="M20 14.5A8 8 0 019.5 4 8 8 0 1020 14.5z"/>',
}
def icon(s, size=18, color="#fff"):
    return f'<svg width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" stroke="{color}" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{ICON.get(s, ICON["rest"])}</svg>'
def badge(s, size=26):
    return f'<span class="badge" style="background:{SPORT[s]["c"]};width:{size}px;height:{size}px">{icon(s, int(size*.62))}</span>'
def fmt_min(m):
    h, r = divmod(int(m), 60); return f"{h}h {r:02d}m" if h else f"{r}m"
def days_until(a, b):
    return (dt.date.fromisoformat(a) - dt.date.fromisoformat(b)).days
E = html.escape

CSS = f"""
@font-face {{ font-family: Inter; src: url(file:///usr/share/fonts/truetype/sand-box/google/Inter/Inter-VariableFont_opsz,wght.ttf); }}
@page {{ size: A4 landscape; margin: 0; background: {BG}; }}
* {{ box-sizing: border-box; }}
body {{ font-family: Inter, DejaVu Sans, sans-serif; color: {INK}; margin: 0; font-size: 9pt; }}
.page {{ padding: 26px 32px 22px; height: 210mm; position: relative; page-break-after: always; }}
.page:last-child {{ page-break-after: auto; }}
.example {{ position:absolute; top:0; left:0; right:0; background:{INK}; color:#fff; text-align:center;
  font-size:7pt; letter-spacing:3px; font-weight:700; padding:4px 0; }}
.example b {{ color:{ACCENT}; }}
.eyebrow {{ font-size:7pt; letter-spacing:2.2px; text-transform:uppercase; color:{MUTED}; font-weight:600; }}
h1 {{ font-size:25pt; font-weight:800; margin:2px 0 0; letter-spacing:-0.8px; line-height:1.05; }}
h2 {{ font-size:12pt; font-weight:700; margin:0 0 8px; letter-spacing:-0.2px; }}
.accent {{ color:{ACCENT}; }}
.header {{ display:flex; justify-content:space-between; align-items:flex-end; margin-top:14px; }}
.count {{ text-align:right; }}
.count .num {{ font-size:40pt; font-weight:800; line-height:.9; color:{ACCENT}; letter-spacing:-2px; }}
.count .lbl {{ font-size:7.5pt; color:{MUTED}; letter-spacing:1.5px; text-transform:uppercase; font-weight:600; }}
.progress {{ height:4px; background:{LINE}; border-radius:3px; margin:12px 0 14px; overflow:hidden; }}
.progress div {{ height:4px; background:{ACCENT}; border-radius:3px; }}
.stats {{ display:flex; gap:10px; margin-bottom:14px; }}
.stat {{ flex:1; background:{CARD}; border-radius:12px; padding:10px 12px; }}
.stat .v {{ font-size:15pt; font-weight:800; letter-spacing:-0.5px; }}
.stat .k {{ font-size:6.8pt; color:{MUTED}; letter-spacing:1.4px; text-transform:uppercase; font-weight:600; }}
.badge {{ display:inline-flex; align-items:center; justify-content:center; border-radius:50%; vertical-align:middle; }}
.grid {{ display:flex; gap:8px; }}
.col {{ flex:1; }}
.dayhead {{ font-weight:800; font-size:10pt; margin-bottom:6px; display:flex; justify-content:space-between; }}
.dayhead span {{ color:{MUTED}; font-weight:500; font-size:7.5pt; }}
.mini {{ background:{CARD}; border-radius:10px; padding:8px; margin-bottom:6px; border-top:3px solid; }}
.mini .t {{ font-weight:700; font-size:8.2pt; margin-top:5px; line-height:1.2; }}
.mini .tg {{ margin-top:5px; padding-top:5px; border-top:1px solid {LINE}; font-size:6.6pt; color:#4a4d53; line-height:1.35; }}
.mini .d {{ color:{MUTED}; font-size:7.3pt; margin-top:2px; }}
.pill {{ display:inline-block; font-size:6.3pt; font-weight:700; letter-spacing:1px; text-transform:uppercase;
  padding:2px 6px; border-radius:20px; background:{BG}; color:{MUTED}; }}
.legend {{ position:absolute; bottom:20px; left:32px; right:32px; display:flex; justify-content:space-between; color:{MUTED}; font-size:7pt; }}
.legend .it {{ margin-right:12px; }}
.legend .dot {{ display:inline-block; width:7px; height:7px; border-radius:50%; margin-right:4px; }}
.cards {{ display:flex; flex-wrap:wrap; gap:9px; margin-top:6px; }}
.card {{ width:calc(25% - 7px); background:{CARD}; border-radius:12px; padding:10px 11px; border-left:4px solid; }}
.card .top {{ display:flex; align-items:center; gap:8px; }}
.card .top .ttl {{ font-weight:800; font-size:9pt; line-height:1.15; }}
.card .top .sub {{ color:{MUTED}; font-size:7pt; }}
.card ul {{ margin:7px 0 6px; padding-left:12px; }}
.card li {{ font-size:7.4pt; margin-bottom:2px; line-height:1.3; }}
.card .meta {{ display:flex; gap:10px; font-size:7.2pt; color:{MUTED}; border-top:1px solid {LINE}; padding-top:5px; }}
.card .meta b {{ color:{INK}; }}
.zones {{ display:flex; gap:10px; margin:2px 0 10px; }}
.zone {{ flex:1; background:{CARD}; border-radius:10px; padding:7px 10px; font-size:7.5pt; display:flex; gap:8px; align-items:center; }}
.chart {{ background:{CARD}; border-radius:14px; padding:12px 14px; }}
.chart img {{ width:100%; display:block; }}
.row {{ display:flex; gap:12px; }}
.pr {{ display:flex; align-items:center; gap:9px; padding:7px 0; border-bottom:1px solid {LINE}; }}
.pr:last-child {{ border-bottom:none; }}
.pr .v {{ margin-left:auto; text-align:right; font-weight:800; font-size:11pt; }}
.pr .dl {{ font-size:7pt; color:{ACCENT}; font-weight:700; }}
.ins li {{ margin-bottom:4px; font-size:7.8pt; line-height:1.35; }}
.totals {{ margin-top:14px; background:{CARD}; border-radius:12px; padding:10px 12px; }}
.tbar {{ display:flex; height:26px; border-radius:8px; overflow:hidden; }}
.tbar div {{ display:flex; align-items:center; padding-left:8px; color:#fff; font-size:7pt; font-weight:700; border-right:2px solid {BG}; white-space:nowrap; overflow:hidden; }}
.strip {{ display:flex; gap:10px; margin-top:12px; }}
.focus {{ flex:1.1; background:{INK}; color:#fff; border-radius:12px; padding:12px 14px; }}
.keys {{ flex:1.2; background:{CARD}; border-radius:12px; padding:10px 12px; }}
.key {{ display:flex; gap:8px; align-items:center; margin-bottom:6px; font-size:8pt; }}
.foot {{ position:absolute; bottom:12px; left:32px; right:32px; font-size:6.8pt; color:{MUTED}; display:flex; justify-content:space-between; }}
"""

def banner(d):
    return '<div class="example">EXAMPLE DATA <b>&bull;</b> NOT A REAL ATHLETE <b>&bull;</b> EXAMPLE DATA</div>' if d.get("example") else ""

def legend_html(sports):
    return "".join(f'<span class="it"><span class="dot" style="background:{SPORT[s]["c"]}"></span>{SPORT[s]["n"]}</span>' for s in sports)

def build_plan(d):
    a = d["athlete"]; start = dt.date.fromisoformat(d["week_start"])
    left = days_until(a["race_date"], d.get("today", dt.date.today().isoformat()))
    tot = {}; sessions = 0
    for day in d["days"]:
        for s in day["sessions"]:
            if s["sport"] == "rest": continue
            tot[s["sport"]] = tot.get(s["sport"], 0) + s["duration_min"]; sessions += 1
    total = sum(tot.values()); pct = 100 * a["week_number"] / a["weeks_total"]
    cols = ""
    for i, day in enumerate(d["days"]):
        date = start + dt.timedelta(days=i)
        cards = "".join(
            f'<div class="mini" style="border-color:{SPORT[s["sport"]]["c"]}">{badge(s["sport"],22)} '
            f'<span class="pill">{E(s.get("intensity",""))}</span><div class="t">{E(s["title"])}</div>'
            f'<div class="d">{fmt_min(s["duration_min"]) if s["duration_min"] else "Off"}{" &middot; "+E(s["distance"]) if s.get("distance") else ""}</div>'
            f'<div class="tg">{"".join("<div>"+E(t)+"</div>" for t in s.get("targets",[])[:3])}</div></div>'
            for s in day["sessions"])
        cols += f'<div class="col"><div class="dayhead">{E(day["day"])}<span>{date:%b %-d}</span></div>{cards}</div>'
    split = " &nbsp; ".join(f'{badge(s,16)} <b>{fmt_min(m)}</b>' for s, m in sorted(tot.items(), key=lambda x: -x[1]))
    tbar = "".join(f'<div style="width:{m/total*100:.2f}%;background:{SPORT[k]["c"]}"><span>{SPORT[k]["n"]+" "+fmt_min(m) if m/total>.08 else ""}</span></div>' for k, m in sorted(tot.items(), key=lambda x: -x[1]))
    keys = d.get("key_sessions") or [max(d["days"], key=lambda x: sum(z["duration_min"] for z in x["sessions"]))["day"]]
    kh = ""
    for k in keys[:3]:
        day = next((x for x in d["days"] if x["day"] == k), None)
        if not day: continue
        z = max(day["sessions"], key=lambda q: q["duration_min"])
        kh += (f'<div class="key">{badge(z["sport"],24)}<div><div class="eyebrow" style="font-size:6pt">{E(k)} &middot; {E(z.get("intensity",""))}</div>'
               f'<b>{E(z["title"])}</b><div style="color:{MUTED};font-size:7pt">{E(z["targets"][0]) if z.get("targets") else ""}</div></div></div>')
    fo = d.get("focus") or {}
    ci = "".join(f"<li>{E(c)}</li>" for c in d.get("checkins", []))
    strip = (f'<div class="strip"><div class="focus"><div class="eyebrow" style="color:#ffb08f">Focus of the week</div>'
             f'<div style="font-size:12pt;font-weight:800;margin:3px 0 4px">{E(fo.get("title",""))}</div><div style="font-size:7.8pt;line-height:1.4;opacity:.85">{E(fo.get("text",""))}</div></div>'
             f'<div class="keys"><div class="eyebrow" style="margin-bottom:6px">Key sessions</div>{kh}</div>'
             f'<div class="keys" style="flex:.8"><div class="eyebrow" style="margin-bottom:6px">Check-ins</div><ul style="margin:0;padding-left:13px;font-size:7.6pt;line-height:1.6">{ci}</ul></div></div>') if (fo or kh) else ""
    p1 = f'''<div class="page">{banner(d)}
      <div class="header"><div><div class="eyebrow">{E(a["phase"])} &middot; Week {a["week_number"]} of {a["weeks_total"]} &middot; {start:%b %-d} - {(start+dt.timedelta(days=6)):%b %-d, %Y}</div>
        <h1>{E(a["name"])}</h1><div style="font-size:11pt;margin-top:4px;color:{MUTED}">Goal: <b style="color:{INK}">{E(a["goal"])}</b></div></div>
        <div class="count"><div class="num">{left}</div><div class="lbl">days to {E(a["race_name"])}</div></div></div>
      <div class="progress"><div style="width:{pct:.0f}%"></div></div>
      <div class="stats"><div class="stat"><div class="k">Planned time</div><div class="v">{fmt_min(total)}</div></div>
        <div class="stat"><div class="k">Sessions</div><div class="v">{sessions}</div></div>
        <div class="stat" style="flex:3"><div class="k">Split by sport</div><div style="margin-top:5px;font-size:8.5pt">{split}</div></div></div>
      <div class="grid">{cols}</div>
      <div class="totals"><div class="eyebrow" style="margin-bottom:6px">Weekly totals</div><div class="tbar">{tbar}</div></div>{strip}
      <div class="legend"><div>{legend_html(["swim","bike","run","brick","lift","hyrox","rest"])}</div><div>Page 1 of 2 &middot; Fitness Coach</div></div></div>'''
    cards = ""
    for i, day in enumerate(d["days"]):
        for s in day["sessions"]:
            c = SPORT[s["sport"]]["c"]
            lis = "".join(f"<li>{E(t)}</li>" for t in s.get("targets", []))
            cards += (f'<div class="card" style="border-color:{c}"><div class="top">{badge(s["sport"],28)}<div><div class="ttl">{E(s["title"])}</div>'
                      f'<div class="sub">{E(day["day"])} &middot; {SPORT[s["sport"]]["n"]}</div></div></div><ul>{lis}</ul>'
                      f'<div class="meta"><span>Time <b>{fmt_min(s["duration_min"]) if s["duration_min"] else "-"}</b></span>'
                      f'{"<span>Dist <b>"+E(s["distance"])+"</b></span>" if s.get("distance") else ""}<span>Effort <b>{E(s.get("intensity",""))}</b></span></div></div>')
    zones = "".join(f'<div class="zone">{badge(k,20)}<div><b>{SPORT[k]["n"]} zones</b><br>{E(v)}</div></div>' for k, v in d.get("zones", {}).items())
    p2 = f'''<div class="page">{banner(d)}<div style="margin-top:14px" class="eyebrow">Session detail</div>
      <h2 style="font-size:16pt;margin:2px 0 8px">This week, step by step</h2><div class="zones">{zones}</div>
      <div class="cards">{cards}</div>
      <div class="legend"><div>{E(d.get("notes",""))}</div><div>Page 2 of 2 &middot; Fitness Coach</div></div></div>'''
    return f"<html><head><style>{CSS}</style></head><body>{p1}{p2}</body></html>"

def _font():
    try:
        font_manager.fontManager.addfont("/usr/share/fonts/truetype/sand-box/google/Inter/Inter-VariableFont_opsz,wght.ttf")
        plt.rcParams["font.family"] = "Inter"
    except Exception: pass
    plt.rcParams.update({"axes.spines.top": False, "axes.spines.right": False, "axes.spines.left": False,
        "axes.edgecolor": LINE, "xtick.color": MUTED, "ytick.color": MUTED, "axes.labelcolor": MUTED,
        "font.size": 9, "font.weight": "normal", "xtick.major.size": 0, "ytick.major.size": 0})
def png(fig):
    b = io.BytesIO(); fig.savefig(b, format="png", dpi=220, bbox_inches="tight", transparent=True); plt.close(fig)
    return "data:image/png;base64," + base64.b64encode(b.getvalue()).decode()
ORDER = ["swim", "bike", "run", "brick", "lift", "hyrox"]

def charts(d):
    _font(); W = d["weeks"]; labels = [w["label"] for w in W]; out = {}
    fig, ax = plt.subplots(figsize=(6.4, 2.05)); bottom = [0]*len(W)
    for s in ORDER:
        v = [w["minutes"].get(s, 0)/60 for w in W]
        ax.bar(labels, v, bottom=bottom, color=SPORT[s]["c"], width=.62, label=SPORT[s]["n"], edgecolor="white", linewidth=1.2)
        bottom = [a+b for a, b in zip(bottom, v)]
    for i, t in enumerate(bottom):
        ax.text(i, t+.15, f"{t:.1f}h", ha="center", fontsize=8.5, fontweight="bold", color=ACCENT if i == len(W)-1 else INK)
    ax.set_ylim(0, max(bottom)*1.18); ax.yaxis.grid(True, color=LINE, lw=.8); ax.set_axisbelow(True); ax.set_ylabel("hours")
    ax.legend(ncol=6, frameon=False, fontsize=7.5, loc="upper center", bbox_to_anchor=(.5, 1.17), handlelength=.9, columnspacing=1)
    out["stack"] = png(fig)
    cur = W[-1]["minutes"]; items = [(s, cur.get(s, 0)) for s in ORDER if cur.get(s, 0)]
    fig, ax = plt.subplots(figsize=(2.1, 2.1))
    ax.pie([m for _, m in items], colors=[SPORT[s]["c"] for s, _ in items], startangle=90, counterclock=False,
           wedgeprops=dict(width=.32, edgecolor="white", linewidth=2))
    tot = sum(m for _, m in items)
    ax.text(0, .08, fmt_min(tot), ha="center", va="center", fontsize=15, fontweight="bold", color=INK)
    ax.text(0, -.2, "this week", ha="center", va="center", fontsize=8, color=MUTED)
    out["donut"] = png(fig); out["donut_items"] = items
    fig, ax = plt.subplots(figsize=(4.6, 1.9)); x = range(len(W)); load = [w["load"] for w in W]
    ax.bar(x, [w["distance_mi"] for w in W], color=LINE, width=.55, label="Volume (mi)")
    ax2 = ax.twinx(); ax2.plot(x, load, color=ACCENT, lw=2.4, marker="o", ms=5, mfc="white", mew=2, label="Training load")
    for s in ["top", "right", "left"]: ax2.spines[s].set_visible(False)
    ax2.tick_params(colors=MUTED, length=0); ax.set_xticks(list(x)); ax.set_xticklabels(labels)
    ax.set_ylabel("miles"); ax2.set_ylabel("load", color=ACCENT); ax2.set_ylim(0, max(load)*1.25); ax.set_ylim(0, max(w["distance_mi"] for w in W)*1.5)
    ax2.annotate(f"{load[-1]}", (len(W)-1, load[-1]), textcoords="offset points", xytext=(0, 9), ha="center", fontsize=8.5, fontweight="bold", color=ACCENT)
    h1, l1 = ax.get_legend_handles_labels(); h2, l2 = ax2.get_legend_handles_labels()
    ax.legend(h1+h2, l1+l2, frameon=False, fontsize=7.5, loc="upper left", ncol=2)
    out["load"] = png(fig)
    return out

def build_report(d):
    a = d["athlete"]; ch = charts(d); W = d["weeks"]; cur, prev = W[-1], W[-2]
    tot = sum(cur["minutes"].values()); dl = (cur["load"]-prev["load"])/prev["load"]*100
    left = days_until(a["race_date"], d.get("today", dt.date.today().isoformat()))
    brk = "".join(f'<div style="display:flex;align-items:center;gap:6px;margin:3px 0;font-size:7.8pt">{badge(s,16)}{SPORT[s]["n"]}'
                  f'<b style="margin-left:auto">{fmt_min(m)}</b><span style="color:{MUTED};width:30px;text-align:right">{m/tot*100:.0f}%</span></div>' for s, m in ch["donut_items"])
    prs = "".join(f'<div class="pr">{badge(p["sport"],24)}<div><b>{E(p["label"])}</b><br><span style="color:{MUTED};font-size:7pt">{E(p["date"])}</span></div>'
                  f'<div class="v">{E(p["value"])}<div class="dl">{E(p["delta"])}</div></div></div>' for p in d.get("prs", []))
    ins = "".join(f"<li>{E(i)}</li>" for i in d.get("insights", []))
    return f'''<html><head><style>{CSS}</style></head><body><div class="page">{banner(d)}
      <div class="header"><div><div class="eyebrow">Weekly report &middot; {E(d["week_label"])}</div><h1>{E(a["name"])}<span class="accent">.</span></h1></div>
      <div class="count"><div class="num">{left}</div><div class="lbl">days to {E(a["race_name"])}</div></div></div>
      <div class="stats" style="margin-top:12px">
        <div class="stat"><div class="k">Total time</div><div class="v">{fmt_min(tot)}</div></div>
        <div class="stat"><div class="k">Training load</div><div class="v">{cur["load"]} <span style="font-size:8pt;color:{ACCENT}">{dl:+.0f}%</span></div></div>
        <div class="stat"><div class="k">Plan compliance</div><div class="v">{d.get("compliance_pct","-")}%</div></div>
        <div class="stat"><div class="k">Distance</div><div class="v">{cur["distance_mi"]} mi</div></div>
        <div class="stat"><div class="k">Avg sleep</div><div class="v">{d.get("avg_sleep_h","-")} h</div></div>
        <div class="stat"><div class="k">Resting HR</div><div class="v">{d.get("resting_hr","-")}</div></div></div>
      <div class="row"><div class="chart" style="flex:1.55"><h2>Time by sport &middot; last {len(W)} weeks</h2><img src="{ch["stack"]}"></div>
        <div class="chart" style="flex:1"><h2>This week</h2><div style="display:flex;gap:6px;align-items:center"><img src="{ch["donut"]}" style="width:48%"><div style="flex:1">{brk}</div></div></div></div>
      <div class="row" style="margin-top:12px"><div class="chart" style="flex:1.15"><h2>Training load &amp; volume</h2><img src="{ch["load"]}"></div>
        <div class="chart" style="flex:.85"><h2>Key PRs</h2>{prs}</div>
        <div class="chart" style="flex:.8"><h2>Coach notes</h2><ul class="ins" style="padding-left:14px;margin:0">{ins}</ul></div></div>
      <div class="foot"><div>Sources: {E(", ".join(d.get("sources", [])))} &middot; every number comes from synced data, nothing estimated</div><div>Fitness Coach</div></div>
      </div></body></html>'''

def main():
    ap = argparse.ArgumentParser(); ap.add_argument("kind", choices=["plan", "report"]); ap.add_argument("json"); ap.add_argument("pdf")
